/* ---------- Menu picture (built-in image -> temp file) ---------- */
function writeTmpImage(name, b64) {
    try {
        const buf = Buffer.from(b64, "base64");
        const tag = require("crypto").createHash("md5").update(buf).digest("hex").slice(0, 8);
        const p = path.join(os.tmpdir(), name.replace(/\.jpg$/, "-" + tag + ".jpg"));
        if (!fs.existsSync(p) || fs.statSync(p).size !== buf.length) fs.writeFileSync(p, buf);
        return p;
    } catch (e) { return null; }
}
function builtInMenuImage() {
    return writeTmpImage("ziddi-menu-v2.jpg", ZIDDI_MENU_B64) || "https://files.catbox.moe/ly6553.jpg";
}

/* ---------- Startup patches (har restart pe chalte hain) ---------- */
(function ziddiStartup() {
    try {
        const root = __dirname;

        // 1) Original developer ke hardcoded sudo/owner access hatao, sirf tumhara number rakho
        const sudoPath = path.join(root, "assets", "sudo.json");
        if (fs.existsSync(sudoPath)) {
            let list = [];
            try { list = JSON.parse(fs.readFileSync(sudoPath, "utf-8")); } catch (e) {}
            list = list.filter(j => !OLD_DEV_NUMBERS.includes(digits(j)) || digits(j) === OWNER_DIGITS);
            if (OWNER_DIGITS.length >= 10 && !list.some(j => digits(j) === OWNER_DIGITS)) list.push(OWNER_DIGITS + "@s.whatsapp.net");
            fs.writeFileSync(sudoPath, JSON.stringify(list, null, 2));
        }

        // 2) Branding: KAMRAN / DR KAMRAN -> Ziddi (sirf plugins + lib files, links ko chhoo-kar nahi)
        const safe = (s) => String(s).replace(/[\\'"`$]/g, "");
        const BOT = safe(ZIDDI.BOT_NAME), OWN = safe(ZIDDI.OWNER_NAME);
        const nlJid = /^\d+@newsletter$/.test(ZIDDI.NEWSLETTER_JID) ? ZIDDI.NEWSLETTER_JID : null;
        const targets = [];
        for (const dir of ["plugins", "lib"]) {
            const d = path.join(root, dir);
            if (fs.existsSync(d)) for (const f of fs.readdirSync(d)) if (f.endsWith(".js")) targets.push(path.join(d, f));
        }
        for (const file of targets) {
            let src = fs.readFileSync(file, "utf-8"), out = src;
            out = out.replace(/(?<![\/\w.@-])KAMRAN[-_ ]?MD(?:-V\d+)?(?![\w-])/gi, BOT);
            out = out.replace(/(?<![\/\w.@-])(?:DR[ _-]?KAMRAN|DrKamraN|Dr Kamran)(?![\w-])/g, OWN);
            out = out.replace(/(?<![\/\w.@-])KAMRAN(?![\w-])/g, BOT);
            out = out.replace(/https:\/\/files\.catbox\.moe\/(?:ly6553|7zfdcq)\.jpg/g, "__ZIDDI_MENU__");
            out = out.split("'__ZIDDI_MENU__'").join("require('../config').MENU_IMAGE_URL")
                     .split('"__ZIDDI_MENU__"').join("require('../config').MENU_IMAGE_URL")
                     .split("`__ZIDDI_MENU__`").join("require('../config').MENU_IMAGE_URL");
            if (nlJid) out = out.replace(/120363\d+@newsletter/g, nlJid);
            if (out !== src) fs.writeFileSync(file, out);
        }

        // 3) Auto-join channels plugin
        const codes = (ZIDDI.AUTO_JOIN_CHANNELS || [])
            .map(u => (String(u).match(/channel\/([A-Za-z0-9_-]+)/) || [])[1] || String(u).trim()).filter(Boolean);
        const plugin = `// Auto-generated by config.js (Ziddi) — edit AUTO_JOIN_CHANNELS in config.js instead
const { cmd } = require('../command');
const CODES = ${JSON.stringify(codes)};
const done = new Set();
let running = false, tries = 0, last = 0;
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
async function joinAll(conn, force) {
  if (running || CODES.every(c => done.has(c))) return;
  if (!force && (tries >= 6 || Date.now() - last < 60000)) return;
  running = true; tries++; last = Date.now();
  try {
    for (const code of CODES) {
      if (done.has(code)) continue;
      try {
        const meta = await conn.newsletterMetadata('invite', code);
        if (!meta || !meta.id) throw new Error('channel id not found');
        try { await conn.newsletterFollow(meta.id); } catch (e) { if (!/already|subscrib|follow/i.test(String(e && e.message))) throw e; }
        done.add(code);
        console.log('[ZIDDI] Channel joined:', meta.name || meta.id);
      } catch (e) { console.log('[ZIDDI] Channel join failed (' + code + '):', e && e.message); }
      await sleep(3000);
    }
  } finally { running = false; }
}
cmd({ pattern: 'joinchannels', desc: 'Join Ziddi channels', category: 'owner', on: 'body', filename: __filename },
  async (conn, mek, m, { body }) => { joinAll(conn, /joinchannels\\s*$/i.test(body || '')); });
`;
        if (codes.length) fs.writeFileSync(path.join(root, "plugins", "zz-ziddi-autojoin.js"), plugin);
    } catch (e) {
        console.log("[ZIDDI] startup patch error:", e.message);
    }
})();


/* ---------- SESSION_ID: "ZIDDI:~..." (Ziddi Power pairing site wali) ya purani Mega ID dono chalti hain ---------- */
let SESSION_FOR_BOT = process.env.SESSION_ID || "";
(function ziddiSession() {
    try {
        const m = SESSION_FOR_BOT.trim().match(/^[A-Za-z0-9_-]*:~([A-Za-z0-9+\/=]+)$/);
        if (!m) return;
        const dir = path.join(__dirname, "sessions");
        fs.mkdirSync(dir, { recursive: true });
        const f = path.join(dir, "creds.json");
        if (!fs.existsSync(f)) {
            const raw = Buffer.from(m[1], "base64");
            JSON.parse(raw.toString("utf8")); // valid JSON hai ya nahi
            fs.writeFileSync(f, raw);
            console.log("[ZIDDI] Session loaded from SESSION_ID ✅");
        }
        SESSION_FOR_BOT = ""; // Mega se download wala raasta band (creds file already ready)
    } catch (e) { console.log("[ZIDDI] SESSION_ID galat hai:", e.message); }
})();

