/* "/" par Ziddi page dikhao (loader ke purane status page ki jagah) */
(function ziddiWebsite() {
    try {
        const http = require("http");
        if (http.Server.prototype.__ziddiPatched) return;
        const orig = http.Server.prototype.emit;
        http.Server.prototype.emit = function (ev, req, res) {
            if (ev === "request" && req && res && req.method === "GET" && /^\/(?:index\.html|kamran\.html)?(?:\?.*)?$/.test(req.url || "")) {
                try {
                    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" });
                    res.end(ziddiPage());
                    return true;
                } catch (e) { /* fall through */ }
            }
            return orig.apply(this, arguments);
        };
        Object.defineProperty(http.Server.prototype, "__ziddiPatched", { value: true });
    } catch (e) { console.log("[ZIDDI] website patch error:", e.message); }
})();

